#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_are_unique() {
        let mut ids: Vec<&str> = SCENARIO_CATALOG.iter().map(|s| s.id).collect();
        ids.sort();
        for w in ids.windows(2) {
            assert_ne!(w[0], w[1], "duplicate scenario id: {}", w[0]);
        }
    }

    #[test]
    fn input_commands_are_well_formed() {
        for s in &SCENARIO_CATALOG {
            assert!(
                !s.input_command.is_empty(),
                "empty input.command in {}",
                s.id
            );
        }
    }

    #[test]
    fn runtime_entries_reference_known_scenarios() {
        let known: std::collections::HashSet<&str> =
            SCENARIO_CATALOG.iter().map(|s| s.id).collect();
        for r in &RUNTIME_SCENARIO_CATALOG {
            assert!(
                known.contains(r.id),
                "runtime scenario {} not in catalog",
                r.id
            );
        }
    }

    #[test]
    fn runtime_payloads_parse_as_json() {
        for r in &RUNTIME_SCENARIO_CATALOG {
            for s in r.timeline {
                serde_json::from_str::<serde_json::Value>(s.payload_json)
                    .unwrap_or_else(|e| panic!("bad payload json in {}: {}", r.id, e));
            }
            if let Some(j) = r.final_response_json {
                serde_json::from_str::<serde_json::Value>(j)
                    .unwrap_or_else(|e| panic!("bad final_response json in {}: {}", r.id, e));
            }
        }
    }
}
